        dp = [-1] * (target + 1)
        dp[0] = 0
        for c in range(1, target + 1):
            for digit_cost in cost:
                if c >= digit_cost and dp[c - digit_cost] != -1:
                    dp[c] = max(dp[c], dp[c - digit_cost] + 1)
        if dp[target] <= 0:
            return "0"
