#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    std::string largestNumber(std::vector<int>& cost, int target) {
        std::vector<int> dp(target + 1, -1);
        dp[0] = 0;
        for (int c = 1; c <= target; ++c) {
            for (int digitCost : cost) {
                if (c >= digitCost && dp[c - digitCost] != -1) {
                    dp[c] = std::max(dp[c], dp[c - digitCost] + 1);
                }
            }
        }
        if (dp[target] <= 0) return "0";
        std::string res = "";
        int cur = target;
        for (int d = 9; d >= 1; --d) {
            int c = cost[d - 1];
            while (cur >= c && dp[cur - c] == dp[cur] - 1) {
                res += std::to_string(d);
                cur -= c;
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String largestNumber(int[] cost, int target) {
        int[] dp = new int[target + 1];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        for (int c = 1; c <= target; c++) {
            for (int digitCost : cost) {
                if (c >= digitCost && dp[c - digitCost] != -1) {
                    dp[c] = Math.max(dp[c], dp[c - digitCost] + 1);
                }
            }
        }
        if (dp[target] <= 0) return "0";
        StringBuilder res = new StringBuilder();
        int cur = target;
        for (int d = 9; d >= 1; d--) {
            int c = cost[d - 1];
            while (cur >= c && dp[cur - c] == dp[cur] - 1) {
                res.append(d);
                cur -= c;
            }
        }
        return res.toString();
    }
}

var largestNumber = function(cost, target) {
    const dp = new Array(target + 1).fill(-1);
    dp[0] = 0;
    for (let c = 1; c <= target; c++) {
        for (const digitCost of cost) {
            if (c >= digitCost && dp[c - digitCost] !== -1) {
                dp[c] = Math.max(dp[c], dp[c - digitCost] + 1);
            }
        }
    }
    if (dp[target] <= 0) return "0";
    const res = [];
    let cur = target;
    for (let d = 9; d >= 1; d--) {
        const c = cost[d - 1];
        while (cur >= c && dp[cur - c] === dp[cur] - 1) {
            res.push(d);
            cur -= c;
        }
    }
    return res.join("");
